variante_1.css:
.sl-lightbox {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.9);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
  z-index: 1050; /* Acima de modais Bootstrap */
}

.sl-lightbox:target {
  opacity: 1;
  pointer-events: auto;
}

.sl-lightbox img {
  max-width: 90%;
  max-height: 90%;
  display: block;
  border-radius: var(--bs-border-radius);
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.5);
}

.sl-lightbox-close {
  position: absolute;
  top: 20px;
  right: 30px;
  color: #fff;
  font-size: 40px;
  text-decoration: none;
  line-height: 1;
  transition: color 0.2s ease;
}

.sl-lightbox-close:hover {
  color: var(--sl-primary);
}

variante_1.js:
document.addEventListener('keydown', function(event) {
  if (event.key === 'Escape') {
    const currentHash = window.location.hash;
    if (currentHash.startsWith('#sl-lightbox-img-')) {
      window.location.hash = ''; // Limpa o hash para fechar o lightbox
    }
  }
});

variante_2.css:
.sl-scroll-snap-container {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch; /* Para iOS Safari */
  gap: 1.5rem; /* Equivalente a g-3 do Bootstrap */
  padding-bottom: 1rem; /* Espaço para a barra de rolagem */
}

.sl-scroll-snap-container::-webkit-scrollbar {
  height: 8px;
}

.sl-scroll-snap-container::-webkit-scrollbar-track {
  background: var(--sl-border);
  border-radius: 10px;
}

.sl-scroll-snap-container::-webkit-scrollbar-thumb {
  background: var(--sl-primary);
  border-radius: 10px;
}

.sl-scroll-snap-item {
  flex: 0 0 auto; /* Impede que os itens encolham */
  width: 75%; /* Ajuste para mostrar mais ou menos itens */
  max-width: 300px; /* Largura máxima para cada item */
  scroll-snap-align: center; /* Alinha ao centro do item */
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

@media (min-width: 768px) {
  .sl-scroll-snap-item {
    width: 40%;
  }
}

@media (min-width: 992px) {
  .sl-scroll-snap-item {
    width: 30%;
  }
}

variante_3.css:
.sl-before-after-container {
  position: relative;
  width: 100%;
  max-width: 800px;
  height: 500px; /* Altura fixa para demonstração, ajuste conforme necessário */
  overflow: hidden;
  border-radius: var(--bs-border-radius);
  box-shadow: var(--bs-box-shadow);
  margin: 0 auto;
  --sl-clip-value: 50%; /* Valor de corte padrão */
}

.sl-before-after-container img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none; /* Impede o arrasto da imagem */
}

.sl-after-image {
  clip-path: inset(0 0 0 var(--sl-clip-value));
}

.sl-slider-input {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  -webkit-appearance: none; /* Esconde o slider padrão */
  appearance: none;
  cursor: ew-resize;
  z-index: 1; /* Acima das imagens */
}

.sl-slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 4px; /* Polegar invisível, o 'handle' será usado */
  height: 100%;
  background: transparent;
  cursor: ew-resize;
}

.sl-slider-input::-moz-range-thumb {
  width: 4px;
  height: 100%;
  background: transparent;
  border: none;
  cursor: ew-resize;
}

.sl-slider-handle {
  position: absolute;
  top: 0;
  left: var(--sl-clip-value);
  transform: translateX(-50%);
  width: 40px; /* Largura do 'handle' */
  height: 100%;
  background-color: #fff;
  border-left: 2px solid var(--sl-primary);
  border-right: 2px solid var(--sl-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: ew-resize;
  z-index: 2; /* Acima do input do slider */
  pointer-events: none; /* Deixa o input do slider lidar com os eventos */
}

.sl-slider-handle::before,
.sl-slider-handle::after {
  content: '';
  position: absolute;
  width: 10px;
  height: 10px;
  border: 2px solid var(--sl-primary);
  border-radius: 50%;
  background-color: #fff;
}

.sl-slider-handle::before {
  left: -15px;
}

.sl-slider-handle::after {
  right: -15px;
}

variante_3.js:
document.addEventListener('DOMContentLoaded', function() {
  const sliderContainer = document.querySelector('.sl-before-after-container');
  const sliderInput = sliderContainer ? sliderContainer.querySelector('.sl-slider-input') : null;

  if (sliderInput) {
    function updateClipPath() {
      const value = sliderInput.value;
      sliderContainer.style.setProperty('--sl-clip-value', value + '%');
    }

    sliderInput.addEventListener('input', updateClipPath);
    updateClipPath(); // Define o estado inicial
  }
});

variante_4.css:
.sl-masonry-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr); /* Padrão: 1 coluna em telas pequenas */
  gap: 1rem;
  align-items: start; /* Permite que itens de diferentes alturas se alinhem ao topo de sua área de grid */
}

@media (min-width: 768px) {
  .sl-masonry-grid {
    grid-template-columns: repeat(2, 1fr); /* 2 colunas em telas médias e maiores */
  }
}

.sl-masonry-item img {
  width: 100%;
  height: auto;
  display: block;
}
